<?php
namespace App\Services;use App\Models\{TransportCalendarException,TransportSchedule,TransportService};use Carbon\Carbon;use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;use Illuminate\Validation\ValidationException;
class TransportScheduleGeneratorService{public function __construct(private TransportSchedulingConflictService$conflicts,private TransportAuditService$audit){}public function resolveDates(TransportSchedule$s):array{$days=$s->days->pluck('day_of_week')->map(fn($v)=>(int)$v)->all();$exceptions=TransportCalendarException::forCompany($s->company_id)->whereDate('exception_date','>=',$s->starts_on)->whereDate('exception_date','<=',$s->ends_on)->where(fn($q)=>$q->where('applies_to_all_routes',true)->orWhere('transport_route_id',$s->transport_route_id))->pluck('exception_date')->map(fn($d)=>Carbon::parse($d)->toDateString())->all();$dates=[];for($date=$s->starts_on->copy();$date->lte($s->ends_on);$date->addDay())if(in_array($date->isoWeekday(),$days)&&!in_array($date->toDateString(),$exceptions))$dates[]=$date->copy();return$dates;}public function preview(TransportSchedule$s):array{return array_map(fn($date)=>$this->attributes($s,$date),$this->resolveDates($s));}public function generate(TransportSchedule$s,int$user):int{return DB::transaction(function()use($s,$user){$created=0;foreach($this->preview($s)as$data){if(TransportService::forCompany($s->company_id)->where('transport_route_id',$s->transport_route_id)->where('scheduled_start_at',$data['scheduled_start_at'])->where('service_type',$s->service_type)->where('shift',$s->shift)->exists())continue;$conflicts=$this->conflicts->conflicts($s->company_id,$data['scheduled_start_at'],$data['scheduled_arrival_at'],$s->vehicle_id,$s->driver_id,$s->monitor_id);if($conflicts)throw ValidationException::withMessages(['schedule'=>'Conflicto de programación en '.implode(', ',$conflicts).' para '.$data['scheduled_start_at']->format('d/m/Y H:i').'.']);TransportService::create($data+['company_id'=>$s->company_id,'uuid'=>(string)Str::uuid(),'transport_route_id'=>$s->transport_route_id,'transport_schedule_id'=>$s->id,'service_type'=>$s->service_type,'shift'=>$s->shift,'planned_vehicle_id'=>$s->vehicle_id,'planned_driver_id'=>$s->driver_id,'planned_monitor_id'=>$s->monitor_id,'status'=>'scheduled','generation_source'=>'recurring_schedule','created_by'=>$user]);$created++;}$this->audit->record($s->company_id,'transport_services_generated','schedule',$s->id,$user,['created'=>$created]);return$created;});}private function attributes(TransportSchedule$s,Carbon$date):array{$start=$date->copy()->setTimeFromTimeString($s->default_start_time);$arrival=$date->copy()->setTimeFromTimeString($s->default_arrival_time);if($s->arrival_next_day||$arrival->lte($start))$arrival->addDay();return['service_date'=>$date->toDateString(),'scheduled_start_at'=>$start,'scheduled_arrival_at'=>$arrival,'route_name_snapshot'=>$s->route->name,'origin_snapshot'=>$s->route->origin,'destination_snapshot'=>$s->route->destination];}}
